1	// The growth-dedup CODE-WORK: detect what the mounted canon changed in the window,
2	// and write the brief the agentic phase starts from.
3	//
4	// A run woken by canon movement used to be told only WHICH declared packs moved.
5	// A pack is a corpus, so that sent the run re-reading all of it for coverage that
6	// mostly predates the window, while the thing that can NEWLY cover a local item —
7	// what the canon ADDED in those days — was nowhere in the dispatch. Detecting it
8	// is deterministic code over the commit records, which is code-work's half of the
9	// task, not the agent's.
10	//
11	// Two kinds of addition, and the second is why a prose-only read is not enough: a
12	// canon **check** enforces its rule on every session and CI pass, which covers a
13	// local item more strongly than a stated line does, and it is invisible in the
14	// prose corpus. The brief carries both.
15	//
16	// The channel is the REPOSITORY, per the code-work contract (task-code-work DESIGN
17	// §3): no code→agent data channel exists, so the brief is written into this
18	// task's own standing tracker issue and the hand-off payload carries only its
19	// number. The body is rewritten each run — it describes THIS window, so a second
20	// copy would be a stale one. The tracker's COMMENTS stay the agentic phase's
21	// prune log; code-work never comments.
22	
23	import { writeFileSync } from 'node:fs';
24	import { pathToFileURL } from 'node:url';
25	import { makeGh } from '../../../../engine/scheduler/signals/gh.mjs';
26	import { loadConfig } from '../../../../engine/checks/helpers/repo-context.mjs';
27	import { findOrCreateTracker, writeTracker } from '../../../../engine/scheduler/tracker.mjs';
28	
29	const log = (s) => console.log(`growth-dedup code_work: ${s}`);
30	
31	// The window this task's own cadence covers — `frequency: 'weekly'` in task.mjs.
32	export const WINDOW_DAYS = 7;
33	
34	// The standing log this task keeps. Its own, named here and nowhere else.
35	export const TRACKER_TITLE = 'Claudinite tracker: Growth Dedup';
36	
37	// A canon pack's file, in the two-root form: the mount prefix is optional because
38	// the canon home runs this same code from its repo root, where the shared packs
39	// ARE `packs/`. A local pack (`.claudinite/local/packs/…`, or the pre-rename
40	// `.claudinite/local_packs/…`) matches neither root — deliberately: it is what
41	// this task prunes, never the yardstick it prunes against.
42	const CANON_PACK_FILE = /^(?:\.claudinite\/shared\/)?packs\/([^/]+)\/.+/;
43	
44	// A rule id as a pack's declared-checks.json spells it — `id`, the key that file
45	// actually uses (`rule` is the settings vocabulary for overriding one, a
46	// different file). A drift guard in the pack's tests parses the real
47	// declared-checks.json through this, because keyed on the wrong word it silently
48	// returns nothing on every real patch while fixtures stay green.
49	const CHECK_ID = /"id"\s*:\s*"([^"]+)"/;
50	
51	// How many added lines one file contributes to the brief. A heavy canon week can
52	// move a whole RULES.md rewrite; the remainder is COUNTED in its place, so a
53	// truncated brief never reads as the complete set of what the canon added.
54	export const MAX_ADDED_LINES_PER_FILE = 40;
55	
56	// The whole brief's budget, against GitHub's 65536-byte issue body. Measured
57	// need: the canon home's own busiest week rendered 350KB unbudgeted, so this is
58	// a live constraint, not a theoretical one. What the budget rations is the added
59	// LINES; every changed file is named regardless, since that list is cheap and is
60	// the run's map of where to look for what the budget left out.
61	export const MAX_BRIEF_BYTES = 60000;
62	
63	/** The declared canon pack a repo path belongs to, or null. */
64	export function canonPackOf(path) {
65	  return CANON_PACK_FILE.exec(path)?.[1] ?? null;
66	}
67	
68	/** The lines a unified-diff patch ADDED, marker stripped. */
69	export function addedLines(patch) {
70	  if (typeof patch !== 'string') return [];
71	  return patch.split('\n')
72	    .filter((l) => l.startsWith('+') && !l.startsWith('+++'))
73	    .map((l) => l.slice(1));
74	}
75	
76	/** The check rule ids a declared-checks.json patch ADDED. */
77	export function addedCheckIds(patch) {
78	  return addedLines(patch).map((l) => CHECK_ID.exec(l)?.[1]).filter(Boolean);
79	}
80	
81	/**
82	 * What the declared canon packs gained in the window. Pure over the commit
83	 * records (`{ sha, message, files: [{ filename, patch }] }`) the API returns.
84	 *
85	 * ADDITIONS ONLY. A line the canon REMOVED can never justify a prune — coverage
86	 * the canon just dropped is coverage that is gone, and a local item carrying it
87	 * has become load-bearing rather than redundant — so a `-` line is not offered
88	 * here as something to prune against.
89	 */
90	export function summarizeCanonWindow(commits, declaredPacks) {
91	  const declared = new Set(declaredPacks ?? []);
92	  const packs = {};
93	  let addedLineCount = 0;
94	  let fileCount = 0;
95	
96	  for (const c of commits ?? []) {
97	    for (const f of c.files ?? []) {
98	      const pack = canonPackOf(f.filename ?? '');
99	      if (!pack || !declared.has(pack)) continue;
100	
101	      const entry = (packs[pack] ??= { files: {}, newCheckIds: [] });
102	      const file = entry.files[f.filename] ?? (fileCount += 1, entry.files[f.filename] = { added: [], patchUnavailable: false });
103	
104	      // GitHub omits `patch` on a very large diff. Say so rather than record the
105	      // file as having added nothing — "the canon did not move here" is the one
106	      // claim this brief must never make falsely.
107	      if (typeof f.patch !== 'string') { file.patchUnavailable = true; continue; }
108	
109	      const added = addedLines(f.patch);
110	      file.added.push(...added);
111	      addedLineCount += added.length;
112	      if (f.filename.endsWith('declared-checks.json')) {
113	        for (const id of addedCheckIds(f.patch)) if (!entry.newCheckIds.includes(id)) entry.newCheckIds.push(id);
114	      }
115	    }
116	  }
117	  return { packs, addedLineCount, fileCount };
118	}
119	
120	/**
121	 * The tracker body: the window's canon additions, as the run's starting point.
122	 *
123	 * Two tiers, because they have different worth per byte. The MAP — each pack's
124	 * new check ids and the paths of every file that moved — is always complete: it
125	 * is what tells the run where to look, and it is cheap. The ADDITIONS are what
126	 * the budget rations, in map order, and what the budget leaves out is counted at
127	 * the end. A brief that quietly showed a prefix of the window would read as the
128	 * whole of it.
129	 */
130	export function renderBrief(summary, { sinceIso }) {
131	  const out = [];
132	  let spent = 0;
133	  const push = (...lines) => { out.push(...lines); spent += lines.join('\n').length + 1; };
134	
135	  push(
136	    `# Canon window diff — since ${sinceIso}`,
137	    '',
138	    'Written by the `growth-dedup` code_work at the top of each run, and rewritten every run:',
139	    'this describes the CURRENT window only. It is where the run starts, not what it may cite —',
140	    'a prune may still quote an older line in one of these packs.',
141	    '',
142	  );
143	  const entries = Object.entries(summary.packs);
144	  if (!entries.length) {
145	    push('No declared canon pack moved in this window. Compare the local packs against the mounted canon as a whole.');
146	    return out.join('\n') + '\n';
147	  }
148	
149	  // Tier 1 — the map.
150	  for (const [pack, { files, newCheckIds }] of entries) {
151	    push(`## ${pack}`, '');
152	    if (newCheckIds.length) {
153	      push(`**New checks** (a check covers a local item more strongly than prose): ${newCheckIds.map((id) => `\`${id}\``).join(', ')}`, '');
154	    }
155	    push('Files that moved:', '');
156	    for (const [path, file] of Object.entries(files)) {
157	      const note = file.patchUnavailable ? ' — no patch (diff too large); read the file whole'
158	        : file.added.length ? '' : ' — removals only, nothing added to prune against';
159	      push(`- \`${path}\`${note}`);
160	    }
161	    push('');
162	  }
163	
164	  // Tier 2 — the additions, in map order, until the budget is spent.
165	  push('## What the canon added', '');
166	  let omitted = 0;
167	  for (const [, { files }] of entries) {
168	    for (const [path, file] of Object.entries(files)) {
169	      if (!file.added.length) continue;
170	      const shown = file.added.slice(0, MAX_ADDED_LINES_PER_FILE);
171	      const rest = file.added.length - shown.length;
172	      const block = [
173	        `### \`${path}\``, '', '```', ...shown, '```',
174	        ...(rest > 0 ? ['', `_…and ${rest} more added line${rest === 1 ? '' : 's'} in this file — read its diff for the rest._`] : []),
175	        '',
176	      ];
177	      if (spent + block.join('\n').length > MAX_BRIEF_BYTES) { omitted += 1; continue; }
178	      push(...block);
179	    }
180	  }
181	  if (omitted) {
182	    push(
183	      '---', '',
184	      `**This brief hit its size budget**: additions for ${omitted} further file${omitted === 1 ? '' : 's'} are not shown.`,
185	      'Every file that moved is named in the map above — read the diff of the omitted ones directly.', '',
186	    );
187	  }
188	  // The map tier is unbudgeted by design, so a window that moved thousands of
189	  // files could still overrun on the map alone. Cut it rather than let the issue
190	  // write 422 and fail the run on its first step — and say that it was cut.
191	  const body = out.join('\n') + '\n';
192	  if (body.length <= MAX_BRIEF_BYTES) return body;
193	  return `${body.slice(0, MAX_BRIEF_BYTES)}\n\n_**Truncated at ${MAX_BRIEF_BYTES} bytes** — this window moved more of the canon than one issue body holds._\n`;
194	}
195	
196	/** The one line the work item shows for why the agent is here. */
197	export function handoffDetail(summary) {
198	  const packs = Object.keys(summary.packs);
199	  if (!packs.length) return 'no canon pack moved in the window — comparing against the mounted canon as a whole';
200	  const checks = packs.reduce((n, p) => n + summary.packs[p].newCheckIds.length, 0);
201	  return `${summary.addedLineCount} added line(s) across ${summary.fileCount} file(s) in ${packs.join(', ')}`
202	    + `, ${checks} new check${checks === 1 ? '' : 's'}`;
203	}
204	
205	// --- the I/O shell -----------------------------------------------------------
206	
207	// Every window commit with its files resolved — the per-commit read is what
208	// carries `patch`, which the listing does not.
209	async function windowCommits(gh, repo, branch, sinceIso) {
210	  const listed = await gh(`/repos/${repo}/commits?sha=${encodeURIComponent(branch)}&since=${sinceIso}&per_page=100`);
211	  if (listed.status !== 200) throw new Error(`commit listing unreadable: GET commits returned ${listed.status}`);
212	  const out = [];
213	  for (const c of listed.json ?? []) {
214	    const { status, json } = await gh(`/repos/${repo}/commits/${c.sha}`);
215	    if (status !== 200) continue; // one unreadable commit is a thinner brief, never a failed run
216	    out.push({ sha: c.sha, message: json?.commit?.message ?? '', files: json?.files ?? [] });
217	  }
218	  return out;
219	}
220	
221	async function main() {
222	  const repo = process.env.GITHUB_REPOSITORY || process.env.CLAUDINITE_REPO;
223	  if (!repo || !repo.includes('/')) throw new Error('GITHUB_REPOSITORY is not set (owner/repo)');
224	  if (!process.env.GITHUB_TOKEN) throw new Error('GITHUB_TOKEN is not set — the scheduler always provides it');
225	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
226	  const branch = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
227	  const gh = makeGh();
228	
229	  const sinceIso = new Date(Date.now() - WINDOW_DAYS * 86400000).toISOString();
230	  // The repo's OWN declaration decides which packs are the yardstick: a canon
231	  // pack it does not declare contributes no prose, no checks and no coverage.
232	  // `loadConfig` normalizes a local pack's `local/<id>` token to the bare id, so
233	  // this list mixes both kinds — and needs no filter, since the mount roots
234	  // `canonPackOf` matches exclude the local tree outright.
235	  const declared = loadConfig(root).packs ?? [];
236	  const summary = summarizeCanonWindow(await windowCommits(gh, repo, branch, sinceIso), declared);
237	
238	  // THIS TASK's tracker, resolved by this task. Every run rewrites the body with
239	  // the window's brief — that brief IS what the agentic phase works from — so it
240	  // is found or created here, and the number is handed on below.
241	  const { number: tracker } = await findOrCreateTracker(gh, repo, TRACKER_TITLE);
242	  await writeTracker(gh, repo, tracker, { body: renderBrief(summary, { sinceIso }) });
243	  const detail = handoffDetail(summary);
244	  log(`tracker #${tracker} carries the brief — ${detail}`);
245	
246	  // ALWAYS hand off. The precondition already decided this run happens, and an
247	  // empty canon window still leaves the repo's fresh local items to re-check, so
248	  // there is no condition here to re-litigate — only work code-work cannot do:
249	  // judging whether an added canon line genuinely covers a local item.
250	  const requestPath = process.env.CLAUDINITE_REQUEST_AGENT;
251	  if (!requestPath) throw new Error('CLAUDINITE_REQUEST_AGENT is not set — cannot hand off to the agentic phase');
252	  // The brief is ON the tracker, so the number is the one thing the agentic phase
253	  // cannot do without: it travels in the hand-off payload's `delivered`, which the
254	  // dispatch renders as an `Issue:` line.
255	  writeFileSync(requestPath, JSON.stringify({
256	    delivered: { issue: tracker },
257	    reason: { code: 'canon-window-diff', detail },
258	  }));
259	}
260	
261	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
262	  main().catch((e) => { console.error(`growth-dedup code_work failed: ${e.message}`); process.exit(1); });
263	}
